composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_ROOT_PASSWORD}}
      XIBO_ADMIN_PASSWORD: {{env.XIBO_ADMIN_PASSWORD}}
    volumes:
      - {{appDataPath}}/data:/var/www/cms/web/library
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: xibo
      MYSQL_USER: xibo
      MYSQL_PASSWORD: {{env.MYSQL_ROOT_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.MYSQL_ROOT_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
